131	const REVIEW_PATTERNS = [
132	  "code review",
133	  "codereview",
134	  "reviewe",
135	  "mach einen code review",
136	  "mache einen code review",
137	  "kompletten code review",
138	  "complete code review",
139	  "audit",
140	  "überprüfe den code",
141	  "ueberpruefe den code",
142	  "prüfe den code",
143	  "prufe den code",
144	  "prüfe die änderungen",
145	  "prufe die anderungen",
146	  "prüfe auf regression",
147	  "prufe auf regression",
148	  "analysiere den diff",
149	  "suche fehler",
150	  "suche risiken",
151	  "fehler und risiken",
152	  "codequalität",
153	  "codequalitat",
154	  "code qualität",
155	  "bewerte die code",
156	  "bewerte den code",
157	  "bewerte die änderungen"
158	];
159	const REVIEW_WORD_BOUNDARY = /\breview\b/i;
160	const DEBUG_PATTERNS = ["debug", "fehler", "bug", "problem", "warum", "why", "error"];
161	const LARGE_CHANGE_PATTERNS = ["refactor", "umstrukturiere", "reorganisiere", "neudesign"];
162	const SMALL_CHANGE_PATTERNS = [
163	  "ändere", "change", "update", "add", "entferne", "remove", "fix",
164	  "füge hinzu", "modifiziere", "modify", "neue funktion", "neues feature",
165	  "new function", "new feature", "baue", "einbauen", "integriere", "implementiere",
166	  "setup", "richte ein", "umsetzen"
167	];
168	const PLAN_PATTERNS = ["plan", "design", "architektur", "architecture", "struktur"];
