170	/**
171	 * Explicit review intent — must win over Agent Mode / coding prefixes.
172	 * Canonical task type remains `review` (hotfix alias: code_review).
173	 */
174	export function matchesReviewIntent(userMessage: string): boolean {
175	  const cleaned = userMessage.toLowerCase();
176	  if (REVIEW_PATTERNS.some((p) => cleaned.includes(p))) {
177	    return true;
178	  }
179	  // Standalone "review" word only when not an implement/fix/refactor request.
180	  if (REVIEW_WORD_BOUNDARY.test(cleaned)) {
181	    const intent = classifyUserExecutionIntent(userMessage);
182	    return intent === "review" || intent === "explain_only" || intent === "inspect";
183	  }
184	  return false;
185	}
