189	/**
190	 * Classify the intent of a user message.
191	 * Determines if this is chat or requires tooling/agent.
192	 */
193	export function classifyTaskType(
194	  userMessage: string,
195	  hasExplicitAgentPrefix?: boolean,
196	  hasFileContext?: boolean,
197	): TaskType {
198	  const cleaned = userMessage.toLowerCase();
199	
200	  // Execution / plan intents beat review and casual chat (e.g. "Implementiere Electron").
201	  const executionIntent = classifyUserExecutionIntent(userMessage);
202	  if (isToolRequiredExecutionIntent(executionIntent) || executionIntent === "plan_only") {
203	    return taskTypeForExecutionIntent(executionIntent);
204	  }
205	
206	  // Explicit review after execution verbs have been ruled out.
207	  if (matchesReviewIntent(cleaned) || executionIntent === "review") {
208	    return "review";
209	  }
210	
211	  // Explicit agent mode overrides remaining intents (coding default).
212	  if (hasExplicitAgentPrefix) {
213	    return "large_code_change";
214	  }
215	
216	  if (DEBUG_PATTERNS.some(p => cleaned.includes(p))) {
217	    return "debugging";
218	  }
219	
220	  if (LARGE_CHANGE_PATTERNS.some(p => cleaned.includes(p))) {
221	    return "large_code_change";
222	  }
223	
224	  if (SMALL_CHANGE_PATTERNS.some(p => cleaned.includes(p))) {
225	    return "small_code_change";
226	  }
227	
228	  if (PLAN_PATTERNS.some(p => cleaned.includes(p))) {
229	    return "planning";
230	  }
231	
232	  // Code context present → slightly elevated
233	  if (hasFileContext) {
234	    return "normal_chat";
235	  }
236	
237	  // Default to casual chat
238	  return "casual_chat";
239	}
