241	export interface IntentClassification {
242	  /** The task type classifyTaskType() would return — identical decision, never changed by this function. */
243	  taskType: TaskType;
244	  /** 0..1 keyword-match ratio for the winning pattern group; 1 for explicit-agent-prefix or the no-match fallback. */
245	  confidence: number;
246	  matchedPatterns: string[];
247	  /** Runner-up task types by confidence, excluding the winner. Empty if nothing else matched. */
248	  alternativeTaskTypes: Array<{ taskType: TaskType; confidence: number }>;
249	}
250	
251	function scorePatternGroup(cleaned: string, patterns: string[]): { confidence: number; matched: string[] } {
252	  const matched = patterns.filter((p) => cleaned.includes(p));
253	  return { confidence: matched.length / patterns.length, matched };
254	}
255	
256	/**
257	 * Same intent decision as classifyTaskType(), plus confidence/alternatives for
258	 * the clarification policy. The winning taskType is always derived by calling
259	 * classifyTaskType() itself, so this can never diverge from it — confidence
260	 * scoring is purely additive diagnostic information layered on top of the
261	 * existing first-match priority chain, not a replacement for it.
262	 */
263	export function classifyTaskTypeDetailed(
264	  userMessage: string,
265	  hasExplicitAgentPrefix?: boolean,
266	  hasFileContext?: boolean,
267	): IntentClassification {
268	  const taskType = classifyTaskType(userMessage, hasExplicitAgentPrefix, hasFileContext);
269	  const cleaned = userMessage.toLowerCase();
270	
271	  if (taskType === "review" && matchesReviewIntent(cleaned)) {
272	    const reviewScore = scorePatternGroup(cleaned, REVIEW_PATTERNS);
273	    return {
274	      taskType: "review",
275	      confidence: reviewScore.confidence > 0 ? reviewScore.confidence : 1,
276	      matchedPatterns: reviewScore.matched.length > 0 ? reviewScore.matched : ["review_intent"],
277	      alternativeTaskTypes: hasExplicitAgentPrefix
278	        ? [{ taskType: "large_code_change", confidence: 1 }]
279	        : []
280	    };
281	  }
282	
283	  if (hasExplicitAgentPrefix) {
284	    return { taskType, confidence: 1, matchedPatterns: ["explicit_agent_prefix"], alternativeTaskTypes: [] };
285	  }
286	
287	  const groups: Array<{ taskType: TaskType; patterns: string[] }> = [
288	    { taskType: "review", patterns: REVIEW_PATTERNS },
289	    { taskType: "debugging", patterns: DEBUG_PATTERNS },
290	    { taskType: "large_code_change", patterns: LARGE_CHANGE_PATTERNS },
291	    { taskType: "small_code_change", patterns: SMALL_CHANGE_PATTERNS },
292	    { taskType: "planning", patterns: PLAN_PATTERNS }
293	  ];
294	
295	  const scored = groups
296	    .map((group) => ({ taskType: group.taskType, ...scorePatternGroup(cleaned, group.patterns) }))
297	    .filter((entry) => entry.confidence > 0);
298	
299	  const winner = scored.find((entry) => entry.taskType === taskType);
300	  const alternativeTaskTypes = scored
301	    .filter((entry) => entry.taskType !== taskType)
302	    .sort((a, b) => b.confidence - a.confidence)
303	    .slice(0, 2)
304	    .map((entry) => ({ taskType: entry.taskType, confidence: entry.confidence }));
305	
306	  return {
307	    taskType,
308	    confidence: winner?.confidence ?? 1,
309	    matchedPatterns: winner?.matched ?? [],
310	    alternativeTaskTypes
311	  };
312	}
