365	/**
366	 * Detect vision / multimodal models by catalog metadata or filename tokens.
367	 */
368	export function looksLikeVisionModel(
369	  value: string,
370	  catalogEntry?: BrokerModelCatalogEntry | null,
371	): boolean {
372	  if (catalogEntry) {
373	    if (isNonRunnableSupportArtifact(catalogEntry)) return false;
374	    if (catalogEntry.recommended_use === "vision_candidate") return true;
375	    if (catalogEntry.capabilities?.includes("vision")) return true;
376	  }
377	
378	  const key = value.toLowerCase().replace(/\\/g, "/");
379	  if (
380	    key.includes("vision") ||
381	    key.includes("llava") ||
382	    key.includes("janus") ||
383	    key.includes("smolvlm") ||
384	    key.includes("qwen2.5-vl") ||
385	    key.includes("qwen2-vl") ||
386	    key.includes("image_text_to_text") ||
387	    key.includes("vision_chat") ||
388	    key.includes("multimodal") ||
389	    key.includes("-vl-") ||
390	    key.includes("-vl.") ||
391	    key.includes("/vl") ||
392	    key.includes("_vl_") ||
393	    key.includes("_vl.")
394	  ) {
395	    return true;
396	  }
397	  return /(^|[^a-z0-9])vl([^a-z0-9]|$)/.test(key);
398	}
