400	function findCatalogEntry(
401	  modelId: string,
402	  catalog?: BrokerModelCatalogEntry[],
403	): BrokerModelCatalogEntry | undefined {
404	  if (!catalog?.length) return undefined;
405	  const normalized = modelId.toLowerCase();
406	  return catalog.find(
407	    (entry) =>
408	      entry.id === modelId ||
409	      entry.name === modelId ||
410	      entry.id.toLowerCase() === normalized ||
411	      (entry.name?.toLowerCase() ?? "") === normalized,
412	  );
413	}
