415	function findVerifiedMultimodalPair(
416	  modelId: string,
417	  multimodalPairs?: MultimodalPair[],
418	): MultimodalPair | undefined {
419	  if (!multimodalPairs?.length) return undefined;
420	  return multimodalPairs.find(
421	    (pair) => pair.base_model_id === modelId && pair.routing_allowed === true,
422	  );
423	}
