425	/** Content-hash / opaque ids must never be shown as the sole model label. */
426	export function looksLikeOpaqueModelId(value: string): boolean {
427	  const base = value.replace(/\\/g, "/").split("/").pop() ?? value;
428	  const stripped = base.replace(/\.(gguf|bin)$/i, "").trim();
429	  if (!stripped) return true;
430	  return /^[a-f0-9]{8,64}$/i.test(stripped);
431	}
432	
433	function isVisionModelRef(modelId: string, catalog?: BrokerModelCatalogEntry[]): boolean {
434	  return looksLikeVisionModel(modelId, findCatalogEntry(modelId, catalog));
435	}
