437	/**
438	 * Whether a (possibly vision) model may handle text-only requests.
439	 * Prefer explicit catalog flags; otherwise infer from Instruct-VL / dual chat+vision caps.
440	 */
441	export function modelSupportsTextOnly(
442	  modelId: string,
443	  catalog?: BrokerModelCatalogEntry[],
444	): boolean {
445	  const entry = findCatalogEntry(modelId, catalog);
446	  if (entry?.supportsTextOnly === true) return true;
447	  if (entry?.supportsTextOnly === false) return false;
448	  if (entry?.requiresVisionProjector === true) return false;
449	  if (entry?.supportsVision === false) return true;
450	
451	  const caps = entry?.capabilities ?? [];
452	  if (caps.includes("vision") && caps.includes("chat")) return true;
453	
454	  const key = `${entry?.name ?? ""} ${modelId}`.toLowerCase();
455	  if (/vl/.test(key) && /instruct/.test(key)) return true;
456	  return false;
457	}
458	
459	export function modelRequiresVisionProjector(
460	  modelId: string,
461	  catalog?: BrokerModelCatalogEntry[],
462	): boolean {
463	  const entry = findCatalogEntry(modelId, catalog);
464	  if (entry?.requiresVisionProjector === true) return true;
465	  if (entry?.supportsTextOnly === false && isVisionModelRef(modelId, catalog)) return true;
466	  return false;
467	}
