469	function taskRequiresCodingCapability(taskType: TaskType): boolean {
470	  return (
471	    taskType === "small_code_change" ||
472	    taskType === "large_code_change" ||
473	    taskType === "refactoring" ||
474	    taskType === "debugging" ||
475	    taskType === "review" ||
476	    taskType === "test_analysis"
477	  );
478	}
