480	function modelSupportsCodingCapability(
481	  modelId: string,
482	  catalog?: BrokerModelCatalogEntry[],
483	): boolean {
484	  const entry = findCatalogEntry(modelId, catalog);
485	  if (!entry) {
486	    return false;
487	  }
488	  return entry.capabilities?.includes("code") === true;
489	}
