491	export function deriveModelDisplayName(
492	  modelId: string,
493	  fallbackName: string,
494	  catalog?: BrokerModelCatalogEntry[],
495	): string {
496	  const entry = findCatalogEntry(modelId, catalog);
497	  if (entry?.name?.trim() && !looksLikeOpaqueModelId(entry.name)) {
498	    return entry.name.trim();
499	  }
500	  const base = modelId.replace(/\\/g, "/").split("/").pop() ?? modelId;
501	  const withoutExt = base.replace(/\.(gguf|bin)$/i, "").trim();
502	  if (withoutExt && withoutExt !== "default" && !looksLikeOpaqueModelId(withoutExt)) {
503	    return withoutExt;
504	  }
505	  if (fallbackName.trim() && !looksLikeOpaqueModelId(fallbackName)) {
506	    return fallbackName.trim();
507	  }
508	  return "Lokales Modell";
509	}
510	
511	/** Prefer a human-readable name; never show a bare hash id. */
512	export function formatModelDisplayLabel(
513	  modelName: string | null | undefined,
514	  modelId: string | null | undefined,
515	  fallback = "Lokales Modell",
516	): string {
517	  const name = modelName?.trim();
518	  if (name && !looksLikeOpaqueModelId(name)) {
519	    return name;
520	  }
521	  const id = modelId?.trim();
522	  if (id && !looksLikeOpaqueModelId(id)) {
523	    return deriveModelDisplayName(id, fallback);
524	  }
525	  return fallback;
526	}
