528	function resolveModelIdWithVisionGate(
529	  preferred: string | undefined,
530	  settings: {
531	    defaultModelId: string;
532	    defaultChatModelId?: string;
533	    defaultPlannerModelId?: string;
534	    defaultCoderModelId?: string;
535	    defaultReviewerModelId?: string;
536	    defaultDebugModelId?: string;
537	  },
538	  allowVision: boolean,
539	  catalog: BrokerModelCatalogEntry[] | undefined,
540	  multimodalPairs: MultimodalPair[] | undefined,
541	  reasons: string[],
542	  manualModelId?: string,
543	): { modelId: string; selectionSource: BindingSelectionSource; fallbackReason?: string } {
544	  if (manualModelId?.trim()) {
545	    const verifiedManualPair = findVerifiedMultimodalPair(manualModelId, multimodalPairs);
546	    if (allowVision && verifiedManualPair) {
547	      reasons.push(`multimodal_pair:routing_allowed:${verifiedManualPair.projector_artifact_id}`);
548	    }
549	    if (
550	      allowVision &&
551	      modelRequiresVisionProjector(manualModelId, catalog) &&
552	      !verifiedManualPair
553	    ) {
554	      reasons.push(`multimodal_pair:missing_verified_pair:${manualModelId}`);
555	      throw new BindingModelError(
556	        `Visionmodell '${manualModelId}' benoetigt ein verifiziertes MMProj-Pairing, aber es ist keine Routing-Freigabe vorhanden.`,
557	        "vision_pairing_required",
558	        ["MM-Pairing verifizieren", "Anderes Modell waehlen", "Abbrechen"]
559	      );
560	    }
561	    if (!allowVision && isVisionModelRef(manualModelId, catalog)) {
562	      reasons.push(`vision_gate:manual_override_warning:${manualModelId}`);
563	    }
564	    return { modelId: manualModelId, selectionSource: "manual_selection" };
565	  }
566	
567	  if (!preferred?.trim()) {
568	    throw new BindingModelError(
569	      "Rollenmodell in Settings fehlt. Bitte default*ModelId für die Zielrolle setzen.",
570	      "role_model_missing",
571	      ["Rollenmodell in Settings wählen", "Abbrechen"]
572	    );
573	  }
574	
575	  if (catalog?.length) {
576	    const entry = findCatalogEntry(preferred, catalog);
577	    if (!entry) {
578	      throw new BindingModelError(
579	        `Konfiguriertes Rollenmodell '${preferred}' ist nicht im Modellindex.`,
580	        "role_model_not_in_index",
581	        ["Anderes Rollenmodell wählen", "Abbrechen"]
582	      );
583	    }
584	  }
585	
586	  const configuredEntry = findCatalogEntry(preferred, catalog);
587	  if (isNonRunnableSupportArtifact(configuredEntry)) {
588	    throw new BindingModelError(
589	      `Konfiguriertes Rollenmodell '${preferred}' ist ein Support-Artefakt (${configuredEntry?.artifact_type ?? "unknown"}) und nicht direkt startbar.`,
590	      "role_model_not_runnable",
591	      ["Anderes Rollenmodell waehlen", "Abbrechen"]
592	    );
593	  }
594	
595	  if (allowVision || !isVisionModelRef(preferred, catalog)) {
596	    const verifiedPair = allowVision ? findVerifiedMultimodalPair(preferred, multimodalPairs) : undefined;
597	    if (allowVision && verifiedPair) {
598	      reasons.push(`multimodal_pair:routing_allowed:${verifiedPair.projector_artifact_id}`);
599	    }
600	    if (allowVision && modelRequiresVisionProjector(preferred, catalog) && !verifiedPair) {
601	      reasons.push(`multimodal_pair:missing_verified_pair:${preferred}`);
602	      throw new BindingModelError(
603	        `Visionmodell '${preferred}' benoetigt ein verifiziertes MMProj-Pairing, aber es ist keine Routing-Freigabe vorhanden.`,
604	        "vision_pairing_required",
605	        ["MM-Pairing verifizieren", "Anderes Rollenmodell waehlen", "Abbrechen"]
606	      );
607	    }
608	    reasons.push(`role_setting:${preferred}`);
609	    return { modelId: preferred, selectionSource: "role_setting" };
610	  }
611	
612	  // Vision role model on a text-only turn: allow only when text-only is supported.
613	  // Silent swaps to another role model are not allowed.
614	  if (modelSupportsTextOnly(preferred, catalog)) {
615	    reasons.push(`role_setting:${preferred}`);
616	    reasons.push("vision_gate:text_only_supported");
617	    reasons.push(`supportsTextOnly:true`);
618	    return { modelId: preferred, selectionSource: "role_setting" };
619	  }
