180	  model: IndexedModel,
181	  slotId: RuntimeSlotId,
182	  options?: { allowVision?: boolean },
183	): number {
184	  let score = 0;
185	
186	  if (model.compatibility === "llama_server_ready") score += 120;
187	  if (model.recommended_use === "primary_coding") score += slotId === "utility" ? 25 : 100;
188	  if (model.recommended_use === "coding_candidate") score += slotId === "utility" ? 15 : 60;
189	  if (model.recommended_use === "chat_candidate") {
190	    score += slotId === "quality_cpu" ? 80 : slotId === "utility" ? 10 : 25;
191	  }
192	  if (model.capabilities?.includes("code")) score += 35;
193	  if (model.capabilities?.includes("chat")) score += 20;
194	  score += sizeHintScore(model, slotId);
